;----------------------------------------------------------------------------
; NIGHTJAR: extended tilesets (gfx ids 8-15). Multi-bank: control seg 10h +
; one gfx segment per tileset (11h, 12h, ...). Reached from ExtDivert (Banks0123
; header gap) when a room's gfx-tileset >= 8. Tileset 8 = editable Building clone.
; LoadExtDispatch maps the tileset's gfx seg to #8000/#A000 (SegBaseExt) then
; mirrors LoadRoomTiles' block + collision load via the stock seg-0 helpers.
; Generated by tools/genextgfx.py.
;----------------------------------------------------------------------------

		    org	#6000			    ; control segment (10h), always mapped to #6000

idxTileSetsExt:	    dw TileSetExt0		    ; gfx id 8

SegBaseExt:	    db 11h	    ; tileset gfx segments

IdxColisTilesExt:   dw CollTilesExt0

TileSetExt0:	    db 1
		    db 87h
		    db 3
		    dw GfxExt0
		    db 21h
		    db 28h
		    db 0A8h
		    dw GfxExt1
		    db 41h
		    db 0D8h

CollTilesExt0:      db	0A7h, 8Fh, 1Fh, 0FCh, 0CCh, 0FFh, 0FFh, 0CCh, 0D3h, 7Fh, 0FFh, 0FFh, 0, 0FAh, 1, 1Fh
		    db	0FFh, 0FFh, 0FFh, 0FFh, 0FFh, 0FFh, 27h, 0BFh, 0FFh, 0FFh, 0FFh, 0FFh, 27h, 0BFh, 0FFh, 0FFh

;--- dispatcher: maps the tileset's gfx seg to #8000/#A000 (BankIn shadows kept),
;    then loads the config blocks + collision. di is in effect from ExtDivert. ---
LoadExtDispatch:
		    ld	    a, (CurrentTileSet)
		    sub	    8				    ; ext tileset index
		    ld	    e, a
		    ld	    d, 0
		    ld	    hl,	SegBaseExt
		    add	    hl,	de
		    ld	    a, (hl)			    ; gfx base segment for this tileset
		    ld	    (8000h), a			    ; map it to #8000 (control stays at #6000)
		    ld	    (BankIn80),	a
		    inc	    a
		    ld	    (0A000h), a			    ; base+1 to #A000
		    ld	    (BankInA0),	a
		    ld	    a, (CurrentTileSet)
		    sub	    8
		    ld	    de,	idxTileSetsExt
		    call    GetPointerDE2A		    ; DE = ext config pointer (seg 10h)
		    push    de
		    pop	    ix
		    ld	    b, 3
LExtBlk:
		    ld	    a, (ix+0)
		    rla					    ; bit7 = load collision?
		    jr	    c, LExtCol
		    call    LoadTileset
		    ld	    de,	5
		    add	    ix,	de
		    djnz    LExtBlk
LExtCol:
		    ld	    a, (CurrentTileSet)
		    sub	    8
		    ld	    hl,	CollisionTiles
		    exx
		    ld	    hl,	IdxColisTilesExt
		    call    ADD_HL_2A
		    ld	    a, (hl)
		    inc	    hl
		    ld	    h, (hl)
		    ld	    l, a
		    ld	    c, 32
LExtCol2:
		    ld	    a, (hl)
		    exx
		    ld	    b, 8
LExtCol3:
		    rlca
		    ld	    d, a
		    and	    1
		    ld	    (hl), a
		    ld	    a, d
		    inc	    l
		    djnz    LExtCol3
		    exx
		    inc	    hl
		    dec	    c
		    jr	    nz,	LExtCol2
		    jp	    SetBanks1_2_3		    ; restore banks 1,2,3, ei, ret to caller

		    ds	    (#8000-$), #ff		    ; pad control to the end of segment 10h

